solution.Solution.cs:
public record ParsedCommand(
    string Name,
    IReadOnlyList<string> Args,
    IReadOnlyDictionary<string, string> Options,
    IReadOnlySet<string> Flags);

public static class CommandParser
{
    public static List<string> Tokenize(string line) => Scan(line).Select(t => t.Text).ToList();

    private static List<(string Text, bool Quoted)> Scan(string line)
    {
        var tokens = new List<(string, bool)>();
        var current = new StringBuilder();
        bool inToken = false, inQuotes = false, quoted = false;
        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];
            if (inQuotes)
            {
                if (c == '\\' && i + 1 < line.Length && (line[i + 1] == '"' || line[i + 1] == '\\')) current.Append(line[++i]);
                else if (c == '"') inQuotes = false;
                else current.Append(c);
            }
            else if (c == '"') { inQuotes = true; inToken = true; quoted = true; }
            else if (c == ' ')
            {
                if (inToken) tokens.Add((current.ToString(), quoted));
                current.Clear();
                inToken = quoted = false;
            }
            else { current.Append(c); inToken = true; }
        }
        if (inQuotes) throw new FormatException("unclosed quote");
        if (inToken) tokens.Add((current.ToString(), quoted));
        return tokens;
    }

    public static ParsedCommand? Parse(string line)
    {
        var tokens = Scan(line);
        if (tokens.Count == 0) return null;
        var args = new List<string>();
        var options = new Dictionary<string, string>();
        var flags = new HashSet<string>();
        bool optionsEnded = false;
        foreach (var (text, quoted) in tokens.Skip(1))
        {
            if (!optionsEnded && !quoted && text == "--") { optionsEnded = true; continue; }
            if (!optionsEnded && !quoted && text.StartsWith("--") && text.Length > 2)
            {
                int eq = text.IndexOf('=');
                if (eq >= 0) options[text[2..eq].ToLowerInvariant()] = text[(eq + 1)..];
                else flags.Add(text[2..].ToLowerInvariant());
                continue;
            }
            args.Add(text);
        }
        return new ParsedCommand(tokens[0].Text.ToLowerInvariant(), args, options, flags);
    }
}

unitTests:
Test("tokenizing", () =>
{
    CheckEq(CommandParser.Tokenize("  add   tea  2 "), new[] { "add", "tea", "2" });
    CheckEq(CommandParser.Tokenize("note \"Lunch with Ada\" x"), new[] { "note", "Lunch with Ada", "x" });
    CheckEq(CommandParser.Tokenize("say \"a \\\"b\\\" \\\\ c\""), new[] { "say", "a \"b\" \\ c" });
    CheckEq(CommandParser.Tokenize("a\"b c\"d \"\""), new[] { "ab cd", "" });
    CheckEq(CommandParser.Tokenize("").Count, 0);
    CheckThrows<FormatException>(() => CommandParser.Tokenize("say \"oops"));
});

Test("parsing a full command", () =>
{
    var c = CommandParser.Parse("ADD 2026-03-01 -12.50 food \"Lunch with Ada\" --Tag=Work --split --note=")!;
    CheckEq(c.Name, "add");
    CheckEq(c.Args, new[] { "2026-03-01", "-12.50", "food", "Lunch with Ada" });
    CheckEq(c.Options["tag"], "Work");
    CheckEq(c.Options["note"], "");
    Check(c.Flags.Contains("split") && c.Flags.Count == 1, "one flag: split");
});

Test("options details", () =>
{
    var c = CommandParser.Parse("x --a=1 --a=2 \"--quoted\" -- --not-an-option --b=3")!;
    CheckEq(c.Options.Count, 1);
    CheckEq(c.Options["a"], "2");
    CheckEq(c.Args, new[] { "--quoted", "--not-an-option", "--b=3" });
    CheckEq(CommandParser.Parse("   "), null);
    CheckEq(CommandParser.Parse("list")!.Args.Count, 0);
    CheckEq(CommandParser.Parse("x -1 --")!.Args, new[] { "-1" });
});

